SELECT YEAR(s.opened_date) opened_year, CASE WHEN s.sqft >= 17472 THEN 'high' WHEN s.sqft >= 4439 THEN 'mid' ELSE 'low' END sqft_bucket, COUNT(*) num_inventory FROM inventory i JOIN stores s ON s.id = i.store_id JOIN products p ON p.id = i.product_id GROUP BY YEAR(s.opened_date), CASE WHEN s.sqft >= 17472 THEN 'high' WHEN s.sqft >= 4439 THEN 'mid' ELSE 'low' END HAVING COUNT(*) > 1 ORDER BY sqft_bucket, num_inventory DESC, opened_year LIMIT 10
